DELETE FROM `quest_offer_reward` WHERE `ID`=94321;
INSERT INTO `quest_offer_reward` (`ID`,`Emote1`,`Emote2`,`Emote3`,`Emote4`,`EmoteDelay1`,`EmoteDelay2`,`EmoteDelay3`,`EmoteDelay4`,`RewardText`,`VerifiedBuild`) VALUES (94321,0,0,0,0,0,0,0,0,'Flasks of Chromatic Resistance are a vital tool when tampering with various elements at once.$B$BDespite my years of practice, I still find myself overwhelmed by these forces when I take my power for granted.$B$BA little boost will go a long way in my research. Should you ever decide to follow in my footsteps, I advise seeking many out long before your trials begin.$B$BThank you for bringing this to me.',0);
DELETE FROM `quest_offer_reward` WHERE `ID`=94337;
INSERT INTO `quest_offer_reward` (`ID`,`Emote1`,`Emote2`,`Emote3`,`Emote4`,`EmoteDelay1`,`EmoteDelay2`,`EmoteDelay3`,`EmoteDelay4`,`RewardText`,`VerifiedBuild`) VALUES (94337,0,0,0,0,0,0,0,0,'Oh thank goodness, you ARE beeping! I was beginning to think my time in the tower was starting to take its toll on me.$B$BYou say that this is the security device I requested? And it is, indeed, called an Alarm-O-Bot? A fun name, but not particularly imaginative if a simple servant came up with it too, hah.$B$BIn any case, this will be a fun trial run. I trust it won''t explode?',0);
DELETE FROM `quest_offer_reward` WHERE `ID`=94351;
INSERT INTO `quest_offer_reward` (`ID`,`Emote1`,`Emote2`,`Emote3`,`Emote4`,`EmoteDelay1`,`EmoteDelay2`,`EmoteDelay3`,`EmoteDelay4`,`RewardText`,`VerifiedBuild`) VALUES (94351,0,0,0,0,0,0,0,0,'Yep, those are the boots I ordered. I had a pair of wonderful snow-trudging shoes that got swapped for some of my usual armor that I tend to have on hand to sell. Didn''t even notice what I sold off until the buyer brought them back and asked for a repair!$B$BEver since then, I''ve been on the hunt for an extra warm, cozy pair of boots for those chilly nights.$B$BAnd now, here they are! Thanks, pal.',0);
DELETE FROM `quest_offer_reward` WHERE `ID`=99203;
INSERT INTO `quest_offer_reward` (`ID`,`Emote1`,`Emote2`,`Emote3`,`Emote4`,`EmoteDelay1`,`EmoteDelay2`,`EmoteDelay3`,`EmoteDelay4`,`RewardText`,`VerifiedBuild`) VALUES (99203,0,0,0,0,0,0,0,0,'You''ve gone on a lot of adventures out there, both here in Skywall, and beyond. $B$BI hope your new armored galestrider will serve you well in your future travels, as well.',0);
DELETE FROM `quest_offer_reward` WHERE `ID`=99209;
INSERT INTO `quest_offer_reward` (`ID`,`Emote1`,`Emote2`,`Emote3`,`Emote4`,`EmoteDelay1`,`EmoteDelay2`,`EmoteDelay3`,`EmoteDelay4`,`RewardText`,`VerifiedBuild`) VALUES (99209,0,0,0,0,0,0,0,0,'Trainin''s done, I see. Good for you! It''s time to pick out your armored ram. Come, I''ll help ye decide.',0);
DELETE FROM `quest_offer_reward` WHERE `ID`=99216;
INSERT INTO `quest_offer_reward` (`ID`,`Emote1`,`Emote2`,`Emote3`,`Emote4`,`EmoteDelay1`,`EmoteDelay2`,`EmoteDelay3`,`EmoteDelay4`,`RewardText`,`VerifiedBuild`) VALUES (99216,0,0,0,0,0,0,0,0,'Excellent, $N. I can see in your eyes that you have made a choice.$B$BI must say the one you have picked seems fond of you already, and it will be nice to have a reminder of home with you as your adventures take you far from Zephras. I hope you will take good care of it, and it of you.$B$BWinds guide you both!',0);
DELETE FROM `quest_offer_reward` WHERE `ID`=99218;
INSERT INTO `quest_offer_reward` (`ID`,`Emote1`,`Emote2`,`Emote3`,`Emote4`,`EmoteDelay1`,`EmoteDelay2`,`EmoteDelay3`,`EmoteDelay4`,`RewardText`,`VerifiedBuild`) VALUES (99218,0,0,0,0,0,0,0,0,'Ah, good. I be seein'' in your eyes that you have made a choice. A fine one at that.$B$BDe one you have picked seems fond of you already, though I am not surprised. I hope you two be taking good care of each other out there in de world.$B$BBlessings of Gonk go wit ya both.',0);
DELETE FROM `quest_offer_reward` WHERE `ID`=99326;
INSERT INTO `quest_offer_reward` (`ID`,`Emote1`,`Emote2`,`Emote3`,`Emote4`,`EmoteDelay1`,`EmoteDelay2`,`EmoteDelay3`,`EmoteDelay4`,`RewardText`,`VerifiedBuild`) VALUES (99326,0,0,0,0,0,0,0,0,'Excellent, $N! I can see you''ve made a choice, and what a fine pick it is.$B$BI''m proud to be able to provide you with one of our horses. I must say the one you have picked seems fond of you already! I hope you will take good care of it, and it of you.$B$BCome back if you ever need new horseshoes! They''re on the house.',0);
DELETE FROM `quest_request_items` WHERE `ID`=94321;
INSERT INTO `quest_request_items` (`ID`,`EmoteOnComplete`,`EmoteOnIncomplete`,`EmoteOnCompleteDelay`,`EmoteOnIncompleteDelay`,`CompletionText`,`VerifiedBuild`) VALUES (94321,0,0,0,0,'Yes?',0);
DELETE FROM `quest_request_items` WHERE `ID`=94337;
INSERT INTO `quest_request_items` (`ID`,`EmoteOnComplete`,`EmoteOnIncomplete`,`EmoteOnCompleteDelay`,`EmoteOnIncompleteDelay`,`CompletionText`,`VerifiedBuild`) VALUES (94337,0,0,0,0,'Greetings, I am afraid that unless--$B$B<Hastings pauses and examines your equipment curiously.>$B$BPardon my asking, but are you beeping?',0);
DELETE FROM `quest_request_items` WHERE `ID`=94351;
INSERT INTO `quest_request_items` (`ID`,`EmoteOnComplete`,`EmoteOnIncomplete`,`EmoteOnCompleteDelay`,`EmoteOnIncompleteDelay`,`CompletionText`,`VerifiedBuild`) VALUES (94351,0,0,0,0,'Hey there, I bet you''ve got that delivery I have been waiting for!',0);
DELETE FROM `quest_request_items` WHERE `ID`=99326;
INSERT INTO `quest_request_items` (`ID`,`EmoteOnComplete`,`EmoteOnIncomplete`,`EmoteOnCompleteDelay`,`EmoteOnIncompleteDelay`,`CompletionText`,`VerifiedBuild`) VALUES (99326,0,0,0,0,'You''ve returned! Have you made your choice? These horses are some of the finest this side of the Eastern Kingdoms.$B$BYou won''t find a more courageous steed.',0);
DELETE FROM `quest_template` WHERE `ID`=94321;
